export type MemberRoleInterest =
  | 'buyer'
  | 'investor'
  | 'jv_partner'
  | 'broker'
  | 'agent'
  | 'land_owner'
  | 'jv_deals'
  | 'tokenized';

export const VALID_ROLE_INTERESTS: ReadonlySet<MemberRoleInterest> = new Set([
  'buyer', 'investor', 'jv_partner', 'broker', 'agent', 'land_owner', 'jv_deals', 'tokenized',
]);

export type MemberStatus =
  | 'free_member'
  | 'investor_pending'
  | 'investor_verified'
  | 'investor_rejected';

/** Which onboarding systems were provisioned at signup (fanout evidence). */
